package မြန်မာ.ကိုယ်ပိုင်;
/** UTF-8 ဘိုက်များနှင့် UTF-16 စာသားကြား ပြောင်းလဲမှု။ စံပုံစံပြောင်းခြင်းနှင့် ပေါင်းစပ်ထည့်သွင်းခြင်းကို သီးခြား ကိရိယာက ဆောင်ရွက်သည်။ */
public final class အက္ခရာ {
    public static int ဘိုက်အရေအတွက်(byte[] ဒေတာ) { return ဒေတာ.length; }
    private အက္ခရာ() {}
    public static int အလျား(String စာသား) { return စာသား.length(); }
    public static boolean ညီစာသား(String ရှေ့တန်ဖိုး, String နောက်တန်ဖိုး) { return ရှေ့တန်ဖိုး == null ? နောက်တန်ဖိုး == null : ရှေ့တန်ဖိုး.equals(နောက်တန်ဖိုး); }
    public static String စာသားကူးထည့်(String ရှေ့တန်ဖိုး, String နောက်တန်ဖိုး) { return ရှေ့တန်ဖိုး.concat(နောက်တန်ဖိုး); }
    public static String တန်ဖိုးဖြတ်(String စာသား, int လုပ်ဆောင်, int အဆုံး) { return စာသား.substring(လုပ်ဆောင်, အဆုံး); }
    public static int ကိန်းပြည့်သဒ္ဒါခွဲခြမ်း(String စာသား) { try { return Integer.parseInt(စာသား); } catch (NumberFormatException အမှား) { throw new ကိန်းပုံစံခြွင်းချက်("ကိန်းဂဏန်းပုံစံနှင့် နယ်နိမိတ်ကို စစ်ဆေးပါ။"); } }
    public static String ကိန်းပြည့်တန်ဖိုးရေး(int ကိန်းတန်ဖိုး) { return Integer.toString(ကိန်းတန်ဖိုး); }
    public static int ကုဒ်အမှတ်တစ်ခုအရေအတွက်(String စာသား) {
        int ကိန်းတန်ဖိုး = 0;
        for (int ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း = 0; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < စာသား.length(); ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++, ကိန်းတန်ဖိုး++) {
            int အက္ခရာကုဒ် = စာသား.charAt(ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း);
            if (အက္ခရာကုဒ် >= 0xd800 && အက္ခရာကုဒ် <= 0xdbff && ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း + 1 < စာသား.length() && စာသား.charAt(ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း + 1) >= 0xdc00 && စာသား.charAt(ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း + 1) <= 0xdfff) ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++;
        }
        return ကိန်းတန်ဖိုး;
    }
    public static byte[] ကုဒ်သွင်း(String စာသား) {
        byte[] ယာယီတန်ဖိုး = new byte[စာသား.length() * 3]; int ရေးပြီးအရေအတွက် = 0;
        for (int ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း = 0; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < စာသား.length(); ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++) {
            int အက္ခရာကုဒ် = စာသား.charAt(ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း);
            if (အက္ခရာကုဒ် >= 0xd800 && အက္ခရာကုဒ် <= 0xdbff && ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း + 1 < စာသား.length() && စာသား.charAt(ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း + 1) >= 0xdc00 && စာသား.charAt(ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း + 1) <= 0xdfff) အက္ခရာကုဒ် = 0x10000 + ((အက္ခရာကုဒ် - 0xd800) << 10) + စာသား.charAt(++ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း) - 0xdc00;
            else if (အက္ခရာကုဒ် >= 0xd800 && အက္ခရာကုဒ် <= 0xdfff) အက္ခရာကုဒ် = '?';
            if (အက္ခရာကုဒ် < 128) ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)အက္ခရာကုဒ်;
            else if (အက္ခရာကုဒ် < 2048) { ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(192 | အက္ခရာကုဒ် >> 6); ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(128 | အက္ခရာကုဒ် & 63); }
            else if (အက္ခရာကုဒ် < 65536) { ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(224 | အက္ခရာကုဒ် >> 12); ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(128 | အက္ခရာကုဒ် >> 6 & 63); ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(128 | အက္ခရာကုဒ် & 63); }
            else { ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(240 | အက္ခရာကုဒ် >> 18); ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(128 | အက္ခရာကုဒ် >> 12 & 63); ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(128 | အက္ခရာကုဒ် >> 6 & 63); ယာယီတန်ဖိုး[ရေးပြီးအရေအတွက်++] = (byte)(128 | အက္ခရာကုဒ် & 63); }
        }
        byte[] ရလဒ် = new byte[ရေးပြီးအရေအတွက်]; System.arraycopy(ယာယီတန်ဖိုး, 0, ရလဒ်, 0, ရေးပြီးအရေအတွက်); return ရလဒ်;
    }
    /** မမှန်သော UTF-8 ကို မမှန်ကန်သော အချက်ခြွင်းချက်ဖြင့် ငြင်းပယ်သည်။ */
    public static String လျှို့ဝှက်ကုဒ်ဖြည်(byte[] ဘိုက်တန်ဖိုး) {
        StringBuilder ရလဒ် = new StringBuilder();
        for (int ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း = 0; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < ဘိုက်တန်ဖိုး.length;) {
            int အက္ခရာကုဒ် = ဘိုက်တန်ဖိုး[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++] & 255, ကိန်းတန်ဖိုး = အက္ခရာကုဒ် < 128 ? 0 : အက္ခရာကုဒ် >= 194 && အက္ခရာကုဒ် < 224 ? 1 : အက္ခရာကုဒ် >= 224 && အက္ခရာကုဒ် < 240 ? 2 : အက္ခရာကုဒ် >= 240 && အက္ခရာကုဒ် <= 244 ? 3 : -1;
            if (ကိန်းတန်ဖိုး < 0 || ဘိုက်တန်ဖိုး.length - ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < ကိန်းတန်ဖိုး) throw new မမှန်ကန်ပေးအချက်ခြွင်းချက်("မမှန်သော UTF-8");
            int အနည်းဆုံးတန်ဖိုး = ကိန်းတန်ဖိုး == 1 ? 128 : ကိန်းတန်ဖိုး == 2 ? 2048 : ကိန်းတန်ဖိုး == 3 ? 65536 : 0;
            if (ကိန်းတန်ဖိုး > 0) အက္ခရာကုဒ် &= (1 << (6 - ကိန်းတန်ဖိုး)) - 1;
            for (int အတွင်းနေရာ = 0; အတွင်းနေရာ < ကိန်းတန်ဖိုး; အတွင်းနေရာ++) { int နောက်တန်ဖိုး = ဘိုက်တန်ဖိုး[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++] & 255; if ((နောက်တန်ဖိုး & 192) != 128) throw new မမှန်ကန်ပေးအချက်ခြွင်းချက်("မမှန်သော UTF-8"); အက္ခရာကုဒ် = အက္ခရာကုဒ် << 6 | နောက်တန်ဖိုး & 63; }
            if (အက္ခရာကုဒ် < အနည်းဆုံးတန်ဖိုး || အက္ခရာကုဒ် > 0x10ffff || အက္ခရာကုဒ် >= 0xd800 && အက္ခရာကုဒ် <= 0xdfff) throw new မမှန်ကန်ပေးအချက်ခြွင်းချက်("မမှန်သော UTF-8");
            if (အက္ခရာကုဒ် < 65536) ရလဒ်.append((char)အက္ခရာကုဒ်);
            else { အက္ခရာကုဒ် -= 65536; ရလဒ်.append((char)(0xd800 | အက္ခရာကုဒ် >> 10)); ရလဒ်.append((char)(0xdc00 | အက္ခရာကုဒ် & 1023)); }
        }
        return ရလဒ်.toString();
    }
}
